public void setPriceDiscPriceUnitMarkup(
    PriceDisc_Price            _priceDisc,
    PriceDiscPolicyCheckPolicy _checkPolicy,
    RetailOrderCalculator _retailCalculator)
{
    next setPriceDiscPriceUnitMarkup(_priceDisc, _checkPolicy, _retailCalculator);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        this.parmPurchLine().ItemBasePriceRecId = _priceDisc.itemBasePriceRecId();
    }
}
